164	    /// <summary>Cuerpo válido con un campo de relleno de N bytes escrito por trozos, sin materializarlo.</summary>
165	    private sealed class CuerpoGrande(long relleno, bool abortarAlMedio = false) : HttpContent
166	    {
167	        protected override async Task SerializeToStreamAsync(Stream stream, TransportContext? context)
168	        {
169	            await stream.WriteAsync(Encoding.UTF8.GetBytes(Prefijo));
170	            var trozo = new byte[64 * 1024];
171	            Array.Fill(trozo, (byte)'a');
172	            long escrito = 0;
173	            while (escrito < relleno)
174	            {
175	                var n = (int)Math.Min(trozo.Length, relleno - escrito);
176	                await stream.WriteAsync(trozo.AsMemory(0, n));
177	                escrito += n;
178	                if (abortarAlMedio && escrito >= relleno / 2) throw new IOException("abortado a mitad de lectura");
179	            }
180	            await stream.WriteAsync(Encoding.UTF8.GetBytes("\"}"));
