234	    private sealed class StreamQueSeCorta(Exception falla) : Stream
235	    {
236	        private int _pos;
237	        private readonly byte[] _ini = Encoding.UTF8.GetBytes(Prefijo + new string('a', 20_000));
238	        public override int Read(byte[] buffer, int offset, int count) => throw falla;
239	        public override ValueTask<int> ReadAsync(Memory<byte> buffer, CancellationToken ct = default)
240	        {
241	            if (_pos >= _ini.Length) throw falla;
242	            var n = Math.Min(Math.Min(buffer.Length, 4096), _ini.Length - _pos);
243	            _ini.AsMemory(_pos, n).CopyTo(buffer);
244	            _pos += n;
245	            return new ValueTask<int>(n);
246	        }
247	        public override Task<int> ReadAsync(byte[] buffer, int offset, int count, CancellationToken ct) =>
248	            ReadAsync(buffer.AsMemory(offset, count), ct).AsTask();
249	        public override bool CanRead => true;
250	        public override bool CanSeek => false;
251	        public override bool CanWrite => false;
252	        public override long Length => throw new NotSupportedException();
253	        public override long Position { get => throw new NotSupportedException(); set => throw new NotSupportedException(); }
254	        public override void Flush() { }
255	        public override long Seek(long offset, SeekOrigin origin) => throw new NotSupportedException();
256	        public override void SetLength(long value) => throw new NotSupportedException();
257	        public override void Write(byte[] buffer, int offset, int count) => throw new NotSupportedException();
258	    }
