5	var builder = WebApplication.CreateBuilder(args);
6	
7	static string ResolverRuta(string? configurada)
8	{
9	    if (!string.IsNullOrWhiteSpace(configurada)) return Path.GetFullPath(configurada);
10	    foreach (var inicio in new[] { AppContext.BaseDirectory, Directory.GetCurrentDirectory() })
11	        for (var d = new DirectoryInfo(inicio); d != null; d = d.Parent)
12	            if (Directory.Exists(Path.Combine(d.FullName, "data", "api"))) return Path.Combine(d.FullName, "data");
13	    return Path.GetFullPath("data");
14	}
15	
16	var ruta = ResolverRuta(builder.Configuration["Datos:Ruta"]);
17	builder.Services.AddSingleton(_ => new Reglamento(Path.Combine(ruta, "reglamento")));
18	builder.Services.AddSingleton(_ => new Datos(Path.Combine(ruta, "api")));
19	builder.Services.AddHttpClient("llm", c => c.Timeout = TimeSpan.FromSeconds(60))
20	    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler { AllowAutoRedirect = false });
21	builder.Services.AddSingleton(sp => Precios.Desde(sp.GetRequiredService<IConfiguration>()));
22	builder.Services.AddSingleton<Auditoria>();
23	builder.Services.AddSingleton<ILlmClient>(sp =>
24	{
25	    var cfg = sp.GetRequiredService<IConfiguration>();
26	    var proveedor = (cfg["LLM_PROVIDER"] ?? "").Trim();
27	    if (proveedor.Length == 0 || proveedor.Equals("openai", StringComparison.OrdinalIgnoreCase))
28	        return ActivatorUtilities.CreateInstance<OpenAiCompatClient>(sp);
29	    if (proveedor.Equals("anthropic", StringComparison.OrdinalIgnoreCase))
30	        return ActivatorUtilities.CreateInstance<AnthropicClient>(sp);
31	    throw new InvalidOperationException("LLM_PROVIDER no es válido: use 'openai' o 'anthropic'.");
32	});
33	builder.Services.AddSingleton<Asistente>();
34	
35	var app = builder.Build();
36	
37	// Carga eager: un dato corrupto falla al arrancar, nunca convierte un 400 en 500.
38	app.Services.GetRequiredService<Reglamento>();
39	app.Services.GetRequiredService<Datos>();
40	app.Services.GetRequiredService<ILlmClient>();
41	app.Services.GetRequiredService<Precios>();
42	
43	app.MapGet("/api/salud", () => Results.Json(new { estado = "ok" }));
44	
45	app.MapPost("/api/asistente/preguntar", async (HttpRequest req, Datos datos, IConfiguration cfg, Asistente asistente,
46	    Auditoria auditoria, Precios precios, ILogger<Program> log) =>
47	{
48	    // Un solo punto de registro: el finally cubre toda ruta de salida.
49	    string? rolAud = null, idAud = null, preguntaAud = null;
50	    var codigo = 500;
51	    IReadOnlyList<Cita> citasAud = [];
52	    var medicion = new MedicionUso();
53	
54	    IResult Error(int c, string msg)
55	    {
56	        codigo = c;
57	        return Results.Json(new { error = msg }, statusCode: c);
58	    }
59	
60	    try
61	    {
62	        const int MaxCuerpo = 64 * 1024;
63	        var limite = req.HttpContext.Features.Get<Microsoft.AspNetCore.Http.Features.IHttpMaxRequestBodySizeFeature>();
64	        if (limite is { IsReadOnly: false }) limite.MaxRequestBodySize = MaxCuerpo;
65	
66	        JsonDocument doc;
67	        try
68	        {
69	            using var ms = new MemoryStream();
70	            var buf = new byte[8192];
71	            int n;
72	            while ((n = await req.Body.ReadAsync(buf, req.HttpContext.RequestAborted)) > 0)
73	            {
74	                if (ms.Length + n > MaxCuerpo) return Error(400, "El cuerpo es demasiado grande.");
75	                ms.Write(buf, 0, n);
76	            }
77	            ms.Position = 0;
78	            doc = await JsonDocument.ParseAsync(ms);
79	        }
80	        catch (JsonException) { return Error(400, "El cuerpo no es un JSON válido."); }
81	        catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
82	        catch (Exception) { return Error(400, "No se pudo leer el cuerpo de la petición."); }
83	
84	        using (doc)
85	        {
86	            var raiz = doc.RootElement;
87	            if (raiz.ValueKind != JsonValueKind.Object) return Error(400, "El cuerpo debe ser un objeto JSON.");
88	
89	            static string? Texto(JsonElement e, string nombre) =>
90	                e.ValueKind == JsonValueKind.Object && e.TryGetProperty(nombre, out var v) && v.ValueKind == JsonValueKind.String
91	                    ? v.GetString() : null;
92	            preguntaAud = Texto(raiz, "pregunta");
93	            if (raiz.TryGetProperty("usuario", out var uAud))
94	            {
95	                rolAud = Texto(uAud, "rol");
96	                idAud = Texto(uAud, "id");
97	            }
98	
99	            if (string.IsNullOrWhiteSpace(preguntaAud)) return Error(400, "La pregunta es obligatoria.");
100	            if (preguntaAud.Length > 1000) return Error(400, "La pregunta no puede superar 1.000 caracteres.");
101	
102	            if (!raiz.TryGetProperty("usuario", out var u) || u.ValueKind != JsonValueKind.Object)
103	                return Error(400, "El usuario es obligatorio.");
104	            if (rolAud == null) return Error(400, "El rol es obligatorio.");
105	            if (rolAud != "estudiante" && rolAud != "coordinador")
106	                return Error(400, "El rol debe ser 'estudiante' o 'coordinador'.");
107	            if (string.IsNullOrWhiteSpace(idAud)) return Error(400, "El id del usuario es obligatorio.");
108	
109	            var usuario = Permisos.ResolverUsuario(datos, rolAud, idAud);
110	            if (usuario == null) return Error(403, "Usuario no válido.");
111	            if (Permisos.MencionaTercero(datos, usuario, preguntaAud))
112	                return Error(403, "No tienes permiso para consultar datos de otros estudiantes.");
113	
114	            if (string.IsNullOrWhiteSpace(cfg["LLM_API_KEY"]))
115	                return Error(503, "El servicio del modelo no está disponible: falta configurar LLM_API_KEY.");
116	
117	            var plazo = double.TryParse(cfg["Asistente:PlazoSegundos"], System.Globalization.NumberStyles.Float,
118	                System.Globalization.CultureInfo.InvariantCulture, out var seg) && seg > 0 ? seg : 90;
119	            using var cts = CancellationTokenSource.CreateLinkedTokenSource(req.HttpContext.RequestAborted);
120	            cts.CancelAfter(TimeSpan.FromSeconds(plazo));
121	
122	            AsistenteResultado res;
123	            try { res = await asistente.ResponderAsync(usuario, preguntaAud, cts.Token, medicion); }
124	            catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
125	            catch (Exception e)
126	            {
127	                log.LogWarning("Falla del asistente o del proveedor ({Tipo}).", e.GetType().Name);
128	                return Error(503, "El proveedor del modelo no está disponible.");
129	            }
130	
131	            if (res.PermisoDenegado) return Error(403, "No tienes permiso para consultar esos datos.");
132	
133	            codigo = 200;
134	            citasAud = res.Citas;
135	            return Results.Json(new
136	            {
137	                respuesta = res.Respuesta,
138	                citas = res.Citas.Select(c => new { documento = c.Documento, seccion = c.Seccion }),
139	                usoDatosEstudiante = res.UsoDatosEstudiante,
140	                tokens = medicion.Total,
141	                costoUsd = precios.Costo(medicion.TokensEntrada, medicion.TokensSalida),
142	            });
143	        }
144	    }
145	    catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested)
146	    {
147	        codigo = 499;
148	        throw;
149	    }
150	    catch (Exception e)
151	    {
152	        log.LogError("Excepción inesperada ({Tipo}).", e.GetType().Name);
153	        return Error(503, "El servicio no está disponible.");
154	    }
155	    finally
156	    {
157	        auditoria.Registrar(new RegistroAuditoria(rolAud, idAud, preguntaAud, medicion.Ids.ToList(), citasAud, codigo,
158	            medicion.Total, precios.Costo(medicion.TokensEntrada, medicion.TokensSalida)));
159	    }
160	});
161	
162	app.Run();
