S=/c/uv-temp/claude/47d8355bb232a04f/c060284e-1856-4c9d-93b9-4c0c73c8f94a/scratchpad; cd $S/copy && cat > tests/TutorFlow.Tests/TmpAdv.cs <<'EOF'
using System.Diagnostics;
using System.Net;
using System.Text;
using Xunit.Abstractions;
namespace TutorFlow.Tests;
public class TmpAdv(ITestOutputHelper o)
{
    static string Rep(string s,int n)=>string.Concat(Enumerable.Repeat(s,n));
    public static IEnumerable<object[]> Casos()
    {
        int N=64*1024;
        yield return new object[]{"anidados", Rep("{",N/2)+Rep("}",N/2)};
        yield return new object[]{"aSt", Rep("{\"a\":\"",N/6)};
        yield return new object[]{"escapadas", Rep("{\"a\\\"",N/5)};
        yield return new object[]{"64x64k", Rep("{"+new string('x',1000)+"}",60)+Rep("{\"a\":\"",9000)};
        yield return new object[]{"llavesCierranNoParsean", Rep("{x}",N/3)};
        yield return new object[]{"64cand", Rep("{"+Rep("\"",1)+new string(' ',1000),64)+Rep("}",N-64000)};
        yield return new object[]{"backticks", "```"+Rep("``` ",N/4)};
        yield return new object[]{"backticks2", "``` "+Rep("a ```x",N/6)};
    }
    [Theory][MemberData(nameof(Casos))]
    public async Task Adv(string n,string txt)
    {
        var llm=new FakeLlmClient().Final("w","[]",1,1).Texto(txt,1,1);
        using var e=new EntornoAuditoria(llm,null);
        await e.Preguntar("w","estudiante","T-E1");
        var sw=Stopwatch.StartNew();
        var (c,_)=await e.Preguntar("x","estudiante","T-E1");
        o.WriteLine($"{n} len={txt.Length} {c} {sw.ElapsedMilliseconds}ms");
    }
    [Fact]
    public async Task Legit()
    {
        using var e=new EntornoAuditoria(new FakeLlmClient().Final("ok","[]",1,1),null);
        var q=string.Concat(Enumerable.Repeat("\\u00e1",1000));
        var body="{\"pregunta\":\""+q+"\",\"usuario\":{\"rol\":\"estudiante\",\"id\":\"T-E1\"}}";
        var (c,b)=await e.Raw(body);
        o.WriteLine($"legit {body.Length} {c}");
        Assert.Equal(HttpStatusCode.OK,c);
    }
}
EOF
dotnet test --nologo --filter TmpAdv --logger "console;verbosity=detailed" 2>&1 | grep -E "len=|legit|Error|error|Fall|Correct" | head -20

